.darma-loader-tw-skeleton-card { display: flex; flex-direction: column; gap: calc(var(--loader-size, 140px) * .06); width: var(--loader-size, 140px); padding: calc(var(--loader-size, 140px) * .07); border-radius: calc(var(--loader-size, 140px) * .1); background: color-mix(in srgb, var(--loader-color, #64748b) 10%, transparent); box-sizing: border-box; animation: darma-loader-tw-skeleton-card-twPulse calc(var(--loader-speed, 1s) * 1.6) cubic-bezier(.4, 0, .6, 1) infinite; }
.darma-loader-tw-skeleton-card .darma-loader-tw-skeleton-card__thumb { height: calc(var(--loader-size, 140px) * .38); border-radius: calc(var(--loader-size, 140px) * .07); background: color-mix(in srgb, var(--loader-color, #64748b) 38%, transparent); }
.darma-loader-tw-skeleton-card .darma-loader-tw-skeleton-card__line { height: calc(var(--loader-size, 140px) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #64748b) 26%, transparent); }
.darma-loader-tw-skeleton-card .darma-loader-tw-skeleton-card__line.darma-loader-tw-skeleton-card__short { width: 60%; }
@keyframes darma-loader-tw-skeleton-card-twPulse { 50% { opacity: .45; } }

